// Pixel Runner – simple endless side‑scroll runner
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // canvas must exist
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 400;

  const GRAVITY = 0.6;
  const JUMP_SPEED = -12;
  const PLAYER_SIZE = 20;
  const GROUND_Y = height - 30;

  const player = {
    x: 50,
    y: GROUND_Y - PLAYER_SIZE,
    w: PLAYER_SIZE,
    h: PLAYER_SIZE,
    vy: 0,
    onGround: true,
    jump() {
      if (this.onGround) {
        this.vy = JUMP_SPEED;
        this.onGround = false;
      }
    },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y + this.h >= GROUND_Y) {
        this.y = GROUND_Y - this.h;
        this.vy = 0;
        this.onGround = true;
      }
    },
    draw() {
      ctx.fillStyle = '#ff0';
      ctx.fillRect(this.x, this.y, this.w, this.h);
    }
  };

  const obstacles = [];
  const OBSTACLE_SPEED = 4;
  const OBSTACLE_MIN_GAP = 120;
  const OBSTACLE_MAX_GAP = 300;
  let nextObstacleIn = OBSTACLE_MIN_GAP;

  function spawnObstacle() {
    const w = 20 + Math.random() * 30;
    const h = 20 + Math.random() * 30;
    obstacles.push({
      x: width,
      y: GROUND_Y - h,
      w,
      h
    });
  }

  function updateObstacles() {
    nextObstacleIn -= OBSTACLE_SPEED;
    if (nextObstacleIn <= 0) {
      spawnObstacle();
      nextObstacleIn = OBSTACLE_MIN_GAP + Math.random() * (OBSTACLE_MAX_GAP - OBSTACLE_MIN_GAP);
    }
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= OBSTACLE_SPEED;
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
  }

  function checkCollision() {
    for (const o of obstacles) {
      if (
        player.x < o.x + o.w &&
        player.x + player.w > o.x &&
        player.y < o.y + o.h &&
        player.y + player.h > o.y
      ) {
        return true;
      }
    }
    return false;
  }

  let gameOver = false;
  function loop() {
    if (gameOver) return;
    ctx.clearRect(0, 0, width, height);
    // ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, GROUND_Y, width, height - GROUND_Y);

    player.update();
    player.draw();

    updateObstacles();
    ctx.fillStyle = '#f33';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y, o.w, o.h);
    }

    if (checkCollision()) {
      gameOver = true;
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
      return;
    }
    requestAnimationFrame(loop);
  }

  // input
  window.addEventListener('keydown', e => {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
      e.preventDefault();
      player.jump();
    }
  });

  // start
  loop();
})();
